Set-Location "c:\git\semio"
function Convert-ToCamelCase([string]$name) {
  if ($name -notmatch '[-_]') {
    return $name
  }
  $parts = $name -split '[-_]+'
  if ($parts.Count -eq 0) {
    return $name
  }
  $head = $parts[0].Substring(0,1).ToLowerInvariant() + $parts[0].Substring(1)
  $tail = foreach ($part in $parts[1..($parts.Count - 1)]) {
    if ([string]::IsNullOrEmpty($part)) { continue }
    if ($part.Length -eq 1) { $part.ToUpperInvariant() }
    else { $part.Substring(0,1).ToUpperInvariant() + $part.Substring(1) }
  }
  return ($head + ($tail -join ''))
}

$files = Get-ChildItem "spatial/assets/modelDefinition" -Recurse -File | Where-Object {
  $_.DirectoryName -match '\\(action|interaction)$'
}

foreach ($file in $files) {
  $baseName = [System.IO.Path]::GetFileNameWithoutExtension($file.Name)
  $camelName = Convert-ToCamelCase $baseName
  if ($camelName -eq $baseName) {
    continue
  }
  $targetPath = Join-Path $file.DirectoryName ($camelName + $file.Extension)
  if (Test-Path $targetPath) {
    throw "Target already exists: $targetPath"
  }
  Move-Item -LiteralPath $file.FullName -Destination $targetPath
}

Write-Output "Renamed action and interaction files to camelCase."

